import{_ as e,o,c as r,l as s,t as n,N as i}from"./chunks/framework.Gjrf2Eoj.js";const q=JSON.parse('{"title":"ipptool | x-cmd man (ip man1) | perform internet printing protocol requests","titleTemplate":false,"description":"x-cmd man (ip man1 Manual Page) | ipptool - perform internet printing protocol requests","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ipptool | x-cmd man (ip man1) | perform internet printing protocol requests"}],["meta",{"name":"og:description","content":"x-cmd man (ip man1 Manual Page) | ipptool - perform internet printing protocol requests"}]]},"headers":[],"params":{"isMan":true,"man":"ipptool","category":"ip man1","desc":"perform internet printing protocol requests"},"relativePath":"ip/man1/ipptool.md","filePath":"ip/man1/ipptool.md"}'),a={name:"ip/man1/ipptool.md"},d={class:"visually-hidden"},p=i(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ipptool - perform internet printing protocol requests</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ipptool</strong> [ <strong>--help</strong> ] [ <strong>--ippserver</strong> <em>filename</em> ] [ <strong>--stop-after-include-error</strong> ] [ <strong>--version</strong> ] [ <strong>-4</strong> ] [ <strong>-6</strong> ] [ <strong>-C</strong> ] [ <strong>-E</strong> ] [ <strong>-I</strong> ] [ <strong>-L</strong> ] [ <strong>-P</strong><em>filename.plist</em> ] [ <strong>-S</strong> ] [ <strong>-T</strong> <em>seconds</em> ] [ <strong>-V</strong><em>version</em> ] [ <strong>-X</strong> ] [ <strong>-c</strong> ] [ <strong>-d</strong> <em>name=value</em> ] [ <strong>-f</strong> <em>filename</em> ] [ <strong>-h</strong> ] [ <strong>-i</strong> <em>seconds</em> ] [ <strong>-j</strong> ] [ <strong>-n</strong> <em>repeat-count</em> ] [ <strong>-q</strong> ] [ <strong>-t</strong> ] [ <strong>-v ]</strong><em>printer-uri</em> <em>testfile</em> [ ... <em>testfile</em> ]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>ipptool</strong> sends IPP requests to the specified <em>printer-uri</em> and tests and/or displays the results. Each named <em>testfile</em> defines one or more requests, including the expected response status, attributes, and values. Output is either a plain text, formatted text, CSV, or XML report on the standard output, with a non-zero exit status indicating that one or more tests have failed. The <em>testfile</em> format is described in <strong>ipptoolfile</strong>(5).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>The following options are recognized by <strong>ipptool:</strong></p><dl><dt><strong>--help</strong></dt><dd>Shows program help.</dd><dt><strong>--ippserver</strong> <em>filename</em></dt><dd>Specifies that the test results should be written to the named <strong>ippserver</strong> attributes file.</dd><dt><strong>--stop-after-include-error</strong></dt><dd>Tells <strong>ipptool</strong> to stop if an error occurs in an included file. Normally <strong>ipptool</strong> will continue with subsequent tests after the INCLUDE directive.</dd><dt><strong>--version</strong></dt><dd>Shows the version of <strong>ipptool</strong> being used.</dd><dt><strong>-4</strong></dt><dd>Specifies that <strong>ipptool</strong> must connect to the printer or server using IPv4.</dd><dt><strong>-6</strong></dt><dd>Specifies that <strong>ipptool</strong> must connect to the printer or server using IPv6.</dd><dt><strong>-C</strong></dt><dd>Specifies that requests should be sent using the HTTP/1.1 &quot;Transfer-Encoding: chunked&quot; header, which is required for conformance by all versions of IPP. The default is to use &quot;Transfer-Encoding: chunked&quot; for requests with attached files and &quot;Content-Length:&quot; for requests without attached files.</dd><dt><strong>-E</strong></dt><dd>Forces TLS encryption when connecting to the server using the HTTP &quot;Upgrade&quot; header.</dd><dt><strong>-I</strong></dt><dd>Specifies that <strong>ipptool</strong> will continue past errors.</dd><dt><strong>-L</strong></dt><dd>Specifies that requests should be sent using the HTTP/1.0 &quot;Content-Length:&quot; header, which is required for conformance by all versions of IPP. The default is to use &quot;Transfer-Encoding: chunked&quot; for requests with attached files and &quot;Content-Length:&quot; for requests without attached files.</dd><dt><strong>-P</strong> * filename.plist*</dt><dd>Specifies that the test results should be written to the named XML (Apple plist) file in addition to the regular test report (<strong>-t</strong>). This option is incompatible with the <strong>-i</strong> (interval) and <strong>-n</strong> (repeat-count) options.</dd><dt><strong>-S</strong></dt><dd>Forces (dedicated) TLS encryption when connecting to the server.</dd><dt><strong>-T</strong> * seconds*</dt><dd>Specifies a timeout for IPP requests in seconds.</dd><dt><strong>-V</strong> * version*</dt><dd>Specifies the default IPP version to use: 1.0, 1.1, 2.0, 2.1, or 2.2. If not specified, version 1.1 is used.</dd><dt><strong>-X</strong></dt><dd>Specifies that XML (Apple plist) output is desired instead of the plain text report. This option is incompatible with the <strong>-i</strong> (interval) and <strong>-n</strong> (repeat-count) options.</dd><dt><strong>-c</strong></dt><dd>Specifies that CSV (comma-separated values) output is desired instead of the plain text output.</dd><dt><strong>-d</strong> * name=value*</dt><dd>Defines the named variable.</dd><dt><strong>-f</strong> * filename*</dt><dd>Defines the default request filename for tests.</dd><dt><strong>-h</strong></dt><dd>Validate HTTP response headers.</dd><dt><strong>-i</strong> * seconds*</dt><dd>Specifies that the (last) <em>testfile</em> should be repeated at the specified interval. This option is incompatible with the <strong>-X</strong> (XML plist output) option.</dd><dt><strong>-j</strong></dt><dd>Specifies that <strong>ipptool</strong> will produce JSON output.</dd><dt><strong>-l</strong></dt><dd>Specifies that plain text output is desired.</dd><dt><strong>-n</strong> * repeat-count*</dt><dd>Specifies that the (last) <em>testfile</em> should be repeated the specified number of times. This option is incompatible with the <em>-X</em> (XML plist output) option.</dd><dt><strong>-q</strong></dt><dd>Be quiet and produce no output.</dd><dt><strong>-t</strong></dt><dd>Specifies that CUPS test report output is desired instead of the plain text output.</dd><dt><strong>-v</strong></dt><dd>Specifies that all request and response attributes should be output in CUPS test mode (<strong>-t</strong>). This is the default for XML output.</dd></dl><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS&quot;">​</a></h2><p>The <strong>ipptool</strong> program returns 0 if all tests were successful and 1 otherwise.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p>The following standard files are available:</p><pre><code>    color.jpg
    create-printer-subscription.test
    document-a4.pdf
    document-a4.ps
    document-letter.pdf
    document-letter.ps
    get-completed-jobs.test
    get-jobs.test
    get-notifications.test
    get-printer-attributes.test
    get-subscriptions.test
    gray.jpg
    ipp-1.1.test
    ipp-2.0.test
    ipp-2.1.test
    ipp-2.2.test
    ipp-everywhere.test
    onepage-a4.pdf
    onepage-a4.ps
    onepage-letter.pdf
    onepage-letter.ps
    print-job.test
    print-job-deflate.test
    print-job-gzip.test
    testfile.jpg
    testfile.pcl
    testfile.pdf
    testfile.ps
    testfile.txt
    validate-job.test
</code></pre><h2 id="conforming-to" tabindex="-1">CONFORMING TO <a class="header-anchor" href="#conforming-to" aria-label="Permalink to &quot;CONFORMING TO&quot;">​</a></h2><p>The <strong>ipptool</strong> program is unique to CUPS and conforms to the Internet Printing Protocol up to version 2.2.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Get a list of completed jobs for &quot;myprinter&quot;:</p><pre><code>    ipptool ipp://localhost/printers/myprinter get-completed-jobs.test
</code></pre><p>Send email notifications to &quot;user@example.com&quot; when &quot;myprinter&quot; changes:</p><pre><code>    ipptool -d recipient=mailto:user@example.com  &lt;br&gt;             ipp://localhost/printers/myprinter create-printer-subscription.test
</code></pre><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>ipptoolfile</strong>(5), IANA IPP Registry (<a href="https://www.iana.org/assignments/ipp-registrations" target="_blank" rel="noreferrer">https://www.iana.org/assignments/ipp-registrations</a>), PWG Internet Printing Protocol Workgroup (<a href="https://www.pwg.org/ipp" target="_blank" rel="noreferrer">https://www.pwg.org/ipp</a>) RFC 8011 (<a href="https://datatracker.ietf.org/doc/html/rfc8011" target="_blank" rel="noreferrer">https://datatracker.ietf.org/doc/html/rfc8011</a>),</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2021-2022 by OpenPrinting.</p>`,25);function l(t,g,h,c,u,m){return o(),r("div",null,[s("h1",d,n(t.$params.man),1),p])}const b=e(a,[["render",l]]);export{q as __pageData,b as default};
